    "tolerans": 0.5,
    "självrättning": true,
    "formaga": [
      "procedur",
      "modellering"
    ],
    "svarFormat": "numeriskt",
    "ledtrad": "<p>Temperaturskillnaden mot 20 °C avtar exponentiellt. Skriv först \\(T(t)=20+60e^{-0{,}25t}\\).</p>",
    "traningsniva": 2,
    "typ": "beräkna temperatur från Newtonmodell",
