    "alternativ": [{"txt": "Att det finns heltal \\(a,b\\) som uppfyller P.", "ratt": true}, {"txt": "Att P alltid är falskt.", "ratt": false}, {"txt": "Att \\(a=b=0\\).", "ratt": false}, {"txt": "Att alla reella tal är heltal.", "ratt": false}]
