    "alternativ": [{"txt": "Alla heltal är jämna.", "ratt": false}, {"txt": "Av två på varandra följande heltal är ett alltid jämnt.", "ratt": true}, {"txt": "\\(n^2\\) är alltid jämnt.", "ratt": false}, {"txt": "\\(n+1\\) är alltid jämnt.", "ratt": false}]
