  "traningsniva": 2,
  "arbetsinsats": 1,
  "ledtrad": "<p>En primitiv funktion till sin x är −cos x.</p>",
  "svarstyp": "numeriskt",
  "rättSvar": 2,
  "tolerans": 0,
  "svarFormat": "numeriskt"
